practice.solution:
import math
def standardise(X):
    n = len(X)
    m = len(X[0])
    out = []
    for i in range(n):
        out.append([0] * m)
    for j in range(m):
        mu = sum([X[i][j] for i in range(n)]) / float(n)
        var = sum([(X[i][j] - mu) ** 2 for i in range(n)]) / float(n)
        sd = math.sqrt(var)
        for i in range(n):
            v = X[i][j] - mu
            if sd > 0:
                v = v / sd
            out[i][j] = round(v, 3)
    return out

