practice.solution:
def outliers(x):
    s = sorted(x)
    def q(p):
        pos = p * (len(s) - 1)
        lo = int(pos)
        if lo + 1 >= len(s):
            return float(s[lo])
        return s[lo] + (pos - lo) * (s[lo + 1] - s[lo])
    q1 = q(0.25)
    q3 = q(0.75)
    iqr = q3 - q1
    lo = q1 - 1.5 * iqr
    hi = q3 + 1.5 * iqr
    return [v for v in x if v < lo or v > hi]

